package work.solour.pulse;
import android.app.*;import android.os.*;import android.content.*;import org.json.*;import java.io.*;import java.util.*;
public class SessionService extends Service {
 public boolean companionMode=false;public int companionMusic=0;public android.media.session.MediaSession mediaSession;public android.media.session.MediaSession.Callback mediaControls;
 public Engine e=new Engine();public final Handler h=new Handler(Looper.getMainLooper()); public Ble ble; public Audio audio;public int style=0;public int target=0;public boolean distanceTarget=false,targetSaid=false; public String lastReport=""; PowerManager.WakeLock wake;long started,previous; final IBinder binder=new Local();public class Local extends Binder {SessionService get(){return SessionService.this;}}
 public IBinder onBind(Intent i){return binder;}public void onCreate(){super.onCreate();NotificationManager nm=getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel("session","同频音乐陪伴",NotificationManager.IMPORTANCE_LOW));ble=new Ble(this);audio=new Audio(this);PowerManager pm=getSystemService(PowerManager.class);wake=pm.newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,"pulse:session");registerReceiver(noisy,new IntentFilter(android.media.AudioManager.ACTION_AUDIO_BECOMING_NOISY));mediaSession=new android.media.session.MediaSession(this,"PULSE companion");mediaControls=new android.media.session.MediaSession.Callback(){public void onPlay(){if(e.running&&e.paused){if(!companionMode)audio.request();pause();}}public void onPause(){if(e.running&&!e.paused)pause();}public void onStop(){if(companionMode&&e.running)endCompanion();}};mediaSession.setCallback(mediaControls,h);mediaSession.setFlags(android.media.session.MediaSession.FLAG_HANDLES_MEDIA_BUTTONS|android.media.session.MediaSession.FLAG_HANDLES_TRANSPORT_CONTROLS);h.post(ticker);}
 Notification notification(){PendingIntent p=PendingIntent.getActivity(this,0,new Intent(this,PulseCompanionActivity.class).addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP|Intent.FLAG_ACTIVITY_CLEAR_TOP),PendingIntent.FLAG_IMMUTABLE);return new Notification.Builder(this,"session").setSmallIcon(android.R.drawable.ic_media_play).setContentTitle("同频 PULSE · "+(companionMode?"音乐陪伴":e.scene)+(e.simulated?" · 模拟":"")).setContentText((e.paused?"已暂停":companionMode?"音乐陪伴中 · 可用耳机播放/暂停":"训练采集与播放中")+(companionMode?" · 点击返回陪伴":" · 点击返回训练")).setOngoing(true).setStyle(companionMode?new Notification.MediaStyle().setMediaSession(mediaSession.getSessionToken()):new Notification.BigTextStyle()).setContentIntent(p).build();}
 public int onStartCommand(Intent i,int flags,int id){refreshForeground();return START_NOT_STICKY;}
 public void refreshForeground(){if(!e.running)return;if(Build.VERSION.SDK_INT>=29){int type=android.content.pm.ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PLAYBACK;boolean bluetoothAllowed=Build.VERSION.SDK_INT<31||checkSelfPermission("android.permission.BLUETOOTH_CONNECT")==android.content.pm.PackageManager.PERMISSION_GRANTED;if(!e.simulated&&bluetoothAllowed)type|=android.content.pm.ServiceInfo.FOREGROUND_SERVICE_TYPE_CONNECTED_DEVICE;startForeground(11,notification(),type);}else startForeground(11,notification());}
 public void begin(String scene,boolean sim,int alert,int rest,int goal,boolean km,int voice,double manual){if(sim)ble.close();e=new Engine();e.scene=scene;e.simulated=sim;e.alert=alert;e.restDefault=rest;e.manualKmh=manual;e.running=true;target=goal;distanceTarget=km;targetSaid=false;style=voice;started=System.currentTimeMillis();previous=SystemClock.elapsedRealtime();startForegroundService(new Intent(this,SessionService.class));wake.acquire();audio.request();if(companionMode&&!audio.focus)e.paused=true;updateMedia();audio.say(companionMode?"音乐陪伴已开始，按你的节奏动起来。":sim?"模拟训练开始，所有数据仅为演示。":"训练开始，按自己的节奏来。",true);}
 public void pause(){if(companionMode&&e.paused){audio.request();if(!audio.focus){updateMedia();getSystemService(NotificationManager.class).notify(11,notification());return;}}e.pause();audio.update();updateMedia();getSystemService(NotificationManager.class).notify(11,notification());}
 final BroadcastReceiver noisy=new BroadcastReceiver(){public void onReceive(Context c,Intent i){if(e.running&&!e.paused){pause();audio.say(companionMode?"耳机已断开，音乐已暂停。":"耳机已断开，训练已暂停。",true);}}};
 final Runnable ticker=new Runnable(){public void run(){long now=SystemClock.elapsedRealtime();while(e.running&&now-previous>=1000){previous+=1000;long sampleTime=previous;if(e.simulated&&!e.paused){e.heart((int)(113+25*Math.sin(e.seconds/30.0)),sampleTime);e.velocity(2.4,sampleTime);if(!e.scene.equals("器械"))e.cadence(e.scene.equals("单车")?80:158,sampleTime);}boolean oldWarning=e.warning;int oldGroups=e.groups.size();e.tick(sampleTime);if(companionMode&&!e.warning){if(companionMusic==1)e.band=2;else if(companionMusic==2)e.band=0;else if(!e.freshHr(sampleTime))e.band=1;}if(!e.paused){audio.update();if(e.warning&&(!oldWarning||e.seconds%30==0))audio.say("心率达到所设警示参考值，请降低强度，必要时停止并寻求帮助。",true);else if(!e.warning){for(int n:e.countdown)audio.say("还剩"+n+"秒",true);if(e.restDone)audio.say("休息结束，准备好后请手动开始。",true);else if(e.groups.size()>oldGroups)audio.say("本组已暂存，请确认推测记录。现在休息。",false);else if(!companionMode&&e.encourage())audio.say(audio.encouragement(),false);}boolean met=target>0&&(e.scene.equals("器械")?e.confirmed>=target:(distanceTarget?e.distance>=target*1000.0:e.seconds>=target*60));if(met&&!targetSaid){targetSaid=true;if(!e.warning)audio.say("目标已达到，可继续或手动结束训练。",false);}}}h.postDelayed(this,200);}};
 public void beginCompanion(){companionMode=true;begin("陪伴",false,getSharedPreferences("pulse-preferences",MODE_PRIVATE).getInt("alert",170),60,0,false,getSharedPreferences("pulse-preferences",MODE_PRIVATE).getInt("style",0),0);}
 public void updateMedia(){if(mediaSession==null)return;mediaSession.setActive(companionMode&&e.running);mediaSession.setPlaybackState(new android.media.session.PlaybackState.Builder().setActions(android.media.session.PlaybackState.ACTION_PLAY|android.media.session.PlaybackState.ACTION_PAUSE|android.media.session.PlaybackState.ACTION_PLAY_PAUSE|android.media.session.PlaybackState.ACTION_STOP).setState(!e.running?android.media.session.PlaybackState.STATE_STOPPED:e.paused?android.media.session.PlaybackState.STATE_PAUSED:android.media.session.PlaybackState.STATE_PLAYING,android.media.session.PlaybackState.PLAYBACK_POSITION_UNKNOWN,e.paused?0f:1f).build());}
 public void endCompanion(){e.running=false;e.curve.clear();audio.onCompleted.clear();audio.tts.stop();audio.focus=false;audio.manager.abandonAudioFocusRequest(audio.req);ble.close();audio.update();updateMedia();if(wake.isHeld())wake.release();stopForeground(true);stopSelf();}
 public JSONArray reports(){try{File f=new File(getFilesDir(),"reports.json");if(!f.exists())return new JSONArray();return new JSONArray(new String(java.nio.file.Files.readAllBytes(f.toPath()),"UTF-8"));}catch(Exception ex){return new JSONArray();}}
 public void save(JSONArray a)throws Exception{File tmp=new File(getFilesDir(),"reports.tmp");try(FileOutputStream out=new FileOutputStream(tmp)){out.write(a.toString().getBytes("UTF-8"));out.getFD().sync();}if(!tmp.renameTo(new File(getFilesDir(),"reports.json")))throw new IOException("保存失败");}
 public JSONObject report()throws Exception{JSONObject r=new JSONObject();r.put("id",UUID.randomUUID().toString());r.put("date",started);r.put("scene",e.scene);r.put("simulation",e.simulated);r.put("seconds",e.seconds);r.put("avg",e.valid==0?JSONObject.NULL:Math.round(e.sum/e.valid));r.put("max",e.valid==0?JSONObject.NULL:e.max);r.put("valid",e.valid);r.put("cadence",e.cadenceCount==0?JSONObject.NULL:Math.round(e.cadenceSum/e.cadenceCount));r.put("metres",Math.round(e.distance));r.put("distanceLabel",e.distanceLabel());r.put("confirmed",e.confirmed);r.put("pending",e.pending());r.put("unfinished",e.groupStart>=0);r.put("curve",new JSONArray(e.curve));JSONArray groups=new JSONArray();for(Engine.Group g:e.groups){JSONObject j=new JSONObject();j.put("start",g.start);j.put("duration",g.duration);j.put("guessed",g.guessed);j.put("confirmed",g.confirmed);groups.put(j);}r.put("groups",groups);return r;}
 public void persistReport(JSONObject r)throws Exception{JSONArray old=reports(),a=new JSONArray();a.put(r);for(int i=0;i<Math.min(99,old.length());i++)a.put(old.get(i));save(a);}
 public JSONObject finish()throws Exception{JSONObject r=report();persistReport(r);lastReport=r.toString();completeFinish();return r;}
 public void completeFinish(){e.running=false;ble.close();audio.update();audio.say("训练结束。时长"+e.seconds/60+"分"+e.seconds%60+"秒。"+(e.valid>0?"平均心率"+Math.round(e.sum/e.valid)+"，最高心率"+e.max+"。":"没有有效心率数据。")+"有效数据覆盖百分之"+(e.seconds==0?0:e.valid*100/e.seconds)+"。"+(e.cadenceCount>0?"平均步频或踏频"+Math.round(e.cadenceSum/e.cadenceCount)+"。":"无有效步频或踏频。")+(e.scene.equals("跑步机")?e.distanceLabel()+Math.round(e.distance)+"米。":e.scene.equals("器械")?"已确认"+e.confirmed+"组，待确认"+e.pending()+"组。":"")+(e.simulated?"这是模拟报告。":""),true);if(wake.isHeld())wake.release();stopForeground(true);stopSelf();}
 public void onDestroy(){h.removeCallbacksAndMessages(null);ble.close();audio.close();if(mediaSession!=null)mediaSession.release();unregisterReceiver(noisy);if(wake.isHeld())wake.release();super.onDestroy();}
}
